-- 000001_init_user_owned.up.sql
-- Initial schema for the health API: user-owned logging tables, template tables,
-- and read-only master reference tables for exercises.
--
-- Conventions:
--   * uuid    - UUID primary key, generated by the Go server (not by the DB).
--   * user_id - UUID owner, resolved by the Go layer from the auth token.
--   * Times are absolute TIMESTAMPTZ; timezone math lives in the Go layer.
--   * Numeric fitness values are DOUBLE PRECISION so the Go server can scan float64.
--   * Soft deletes use `is_deleted`; queries filter `WHERE is_deleted = false`.
--   * No Postgres extensions are used beyond plpgsql.

-- ---------------------------------------------------------------------------
-- updated_at trigger function
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------
-- Master reference tables (read-only, populated from the master seed)
-- ---------------------------------------------------------------------------

CREATE TABLE exercise_categories (
    category_key  TEXT PRIMARY KEY,
    display_order INTEGER NOT NULL DEFAULT 0,
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE exercise_category_translations (
    category_key TEXT NOT NULL REFERENCES exercise_categories (category_key) ON DELETE CASCADE,
    locale       TEXT NOT NULL,
    display_name TEXT NOT NULL,
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (category_key, locale)
);

CREATE TABLE exercise_definitions (
    exercise_key  TEXT PRIMARY KEY,
    category_key  TEXT REFERENCES exercise_categories (category_key) ON DELETE SET NULL,
    is_compound   BOOLEAN NOT NULL DEFAULT false,
    default_name  TEXT NOT NULL,
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE exercise_translations (
    exercise_key TEXT NOT NULL REFERENCES exercise_definitions (exercise_key) ON DELETE CASCADE,
    locale       TEXT NOT NULL,
    display_name TEXT NOT NULL,
    aliases      JSONB NOT NULL DEFAULT '[]'::jsonb,
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (exercise_key, locale)
);

CREATE TABLE one_rm_formulas (
    exercise_key        TEXT PRIMARY KEY REFERENCES exercise_definitions (exercise_key) ON DELETE CASCADE,
    formula_type        TEXT NOT NULL DEFAULT '',
    coefficients        JSONB NOT NULL DEFAULT '{}'::jsonb,
    source              TEXT NOT NULL DEFAULT '',
    optimal_rep_max     INTEGER NOT NULL DEFAULT 0,
    notice_translations JSONB NOT NULL DEFAULT '{}'::jsonb,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- User-owned tables
-- ---------------------------------------------------------------------------

CREATE TABLE user_profiles (
    uuid               UUID PRIMARY KEY,
    user_id            UUID NOT NULL,
    gender             TEXT NOT NULL DEFAULT 'male',
    age                INTEGER NOT NULL DEFAULT 30,
    height_m           DOUBLE PRECISION NOT NULL DEFAULT 1.7,
    goal               TEXT NOT NULL DEFAULT 'diet',
    activity_level     TEXT NOT NULL DEFAULT 'moderate',
    training_intensity TEXT NOT NULL DEFAULT 'moderate',
    target_calories    INTEGER NOT NULL DEFAULT 0,
    target_carbs       DOUBLE PRECISION NOT NULL DEFAULT 0,
    target_protein     DOUBLE PRECISION NOT NULL DEFAULT 0,
    target_fat         DOUBLE PRECISION NOT NULL DEFAULT 0,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT user_profiles_user_id_key UNIQUE (user_id)
);

CREATE TABLE daily_routine (
    uuid       UUID PRIMARY KEY,
    user_id    UUID NOT NULL,
    date       DATE NOT NULL,
    items_json JSONB NOT NULL DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT daily_routine_user_date_key UNIQUE (user_id, date)
);

CREATE TABLE workout_routines (
    uuid       UUID PRIMARY KEY,
    user_id    UUID NOT NULL,
    name       TEXT NOT NULL DEFAULT '',
    items_json JSONB NOT NULL DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    is_deleted BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE food_templates (
    uuid       UUID PRIMARY KEY,
    user_id    UUID NOT NULL,
    name       TEXT NOT NULL,
    carbs      DOUBLE PRECISION NOT NULL DEFAULT 0,
    protein    DOUBLE PRECISION NOT NULL DEFAULT 0,
    fat        DOUBLE PRECISION NOT NULL DEFAULT 0,
    calories   INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    is_deleted BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE exercise_templates (
    uuid                  UUID PRIMARY KEY,
    user_id               UUID NOT NULL,
    name                  TEXT NOT NULL,
    exercise_type         TEXT NOT NULL DEFAULT '',
    exercise_key          TEXT,
    category_key          TEXT,
    rest_seconds_override INTEGER,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    is_deleted            BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE weight_records (
    uuid        UUID PRIMARY KEY,
    user_id     UUID NOT NULL,
    recorded_at TIMESTAMPTZ NOT NULL,
    weight      DOUBLE PRECISION NOT NULL DEFAULT 0,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    is_deleted  BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE diet_records (
    uuid           UUID PRIMARY KEY,
    user_id        UUID NOT NULL,
    recorded_at    TIMESTAMPTZ NOT NULL,
    meal_type      TEXT NOT NULL DEFAULT '',
    food_name      TEXT NOT NULL DEFAULT '',
    carbs          DOUBLE PRECISION NOT NULL DEFAULT 0,
    protein        DOUBLE PRECISION NOT NULL DEFAULT 0,
    fat            DOUBLE PRECISION NOT NULL DEFAULT 0,
    total_calories INTEGER NOT NULL DEFAULT 0,
    satisfaction   INTEGER NOT NULL DEFAULT 0,
    memo           TEXT NOT NULL DEFAULT '',
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    is_deleted     BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE exercise_records (
    uuid          UUID PRIMARY KEY,
    user_id       UUID NOT NULL,
    recorded_at   TIMESTAMPTZ NOT NULL,
    exercise_type TEXT NOT NULL DEFAULT '',
    exercise_name TEXT NOT NULL,
    exercise_key  TEXT,
    category_key  TEXT,
    current_set   INTEGER NOT NULL DEFAULT 1,
    weight        DOUBLE PRECISION NOT NULL DEFAULT 0,
    reps          INTEGER NOT NULL DEFAULT 0,
    rpe           DOUBLE PRECISION NOT NULL DEFAULT 0,
    set_type      TEXT NOT NULL DEFAULT 'work'
                  CONSTRAINT exercise_records_set_type_check
                  CHECK (set_type IN ('warmup', 'work', 'drop', 'failure')),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    is_deleted    BOOLEAN NOT NULL DEFAULT false
);

-- ---------------------------------------------------------------------------
-- Indexes
-- ---------------------------------------------------------------------------

-- Recent-first history per user, live rows only.
CREATE INDEX exercise_records_user_recorded_at_idx
    ON exercise_records (user_id, recorded_at DESC) WHERE is_deleted = false;
CREATE INDEX diet_records_user_recorded_at_idx
    ON diet_records (user_id, recorded_at DESC) WHERE is_deleted = false;
CREATE INDEX weight_records_user_recorded_at_idx
    ON weight_records (user_id, recorded_at DESC) WHERE is_deleted = false;

-- Template listings per user, live rows only.
CREATE INDEX exercise_templates_user_id_idx
    ON exercise_templates (user_id) WHERE is_deleted = false;
CREATE INDEX food_templates_user_id_idx
    ON food_templates (user_id) WHERE is_deleted = false;
CREATE INDEX workout_routines_user_id_idx
    ON workout_routines (user_id) WHERE is_deleted = false;

-- Template names are unique per user among live rows (mirrors the Flutter client).
CREATE UNIQUE INDEX exercise_templates_user_id_name_key
    ON exercise_templates (user_id, name) WHERE is_deleted = false;
CREATE UNIQUE INDEX food_templates_user_id_name_key
    ON food_templates (user_id, name) WHERE is_deleted = false;

-- Master lookup paths.
CREATE INDEX exercise_translations_locale_idx ON exercise_translations (locale);
CREATE INDEX exercise_definitions_category_key_idx ON exercise_definitions (category_key);

-- ---------------------------------------------------------------------------
-- updated_at triggers
-- ---------------------------------------------------------------------------

CREATE TRIGGER exercise_categories_set_updated_at
    BEFORE UPDATE ON exercise_categories
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER exercise_category_translations_set_updated_at
    BEFORE UPDATE ON exercise_category_translations
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER exercise_definitions_set_updated_at
    BEFORE UPDATE ON exercise_definitions
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER exercise_translations_set_updated_at
    BEFORE UPDATE ON exercise_translations
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER one_rm_formulas_set_updated_at
    BEFORE UPDATE ON one_rm_formulas
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER user_profiles_set_updated_at
    BEFORE UPDATE ON user_profiles
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER daily_routine_set_updated_at
    BEFORE UPDATE ON daily_routine
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER workout_routines_set_updated_at
    BEFORE UPDATE ON workout_routines
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER food_templates_set_updated_at
    BEFORE UPDATE ON food_templates
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER exercise_templates_set_updated_at
    BEFORE UPDATE ON exercise_templates
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER weight_records_set_updated_at
    BEFORE UPDATE ON weight_records
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER diet_records_set_updated_at
    BEFORE UPDATE ON diet_records
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER exercise_records_set_updated_at
    BEFORE UPDATE ON exercise_records
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
